import{_ as e,o as n,c as s,a0 as t}from"./chunks/framework.BxCN1dRw.js";const g=JSON.parse('{"title":"Axum SaaS Template — an open-source template you learn from by running it","description":"A Rust + React foundation for your next SaaS, with a working application to learn from.","frontmatter":{"docLocale":"en","counterpart":"/","layout":"page","sidebar":false,"title":"Axum SaaS Template — an open-source template you learn from by running it","description":"A Rust + React foundation for your next SaaS, with a working application to learn from."},"headers":[],"relativePath":"en/index.md","filePath":"en/index.md"}'),i={name:"en/index.md"};function r(o,a,l,d,c,p){return n(),s("div",null,[...a[0]||(a[0]=[t('<div class="landing"><section class="landing-hero"><p class="landing-eyebrow">Open-source template · MIT license</p><h1>A Rust + React foundation for your next SaaS</h1><p class="landing-lede"> A working application to learn from and to build on. Registration, sessions, members, rate limits, jobs, deployment and backup are not roadmap promises — they are capabilities you can start, verify and replace today. </p><p class="landing-actions"><a class="landing-button landing-button-primary" href="docs/">Documentation</a><a class="landing-button" href="https://github.com/CaiZongyuan/axum-saas-template">GitHub repository</a></p></section><section class="landing-section"><h2 class="landing-heading">How you use it</h2><div class="landing-steps"><a class="landing-step" href="getting-started/quickstart"><span class="landing-step-num">1</span><h3>Start the full stack</h3><p>After cloning, one <code>just dev</code> brings up the API, the worker, the web app, PostgreSQL, Redis, RustFS and Mailpit.</p></a><a class="landing-step" href="tutorials/first-request"><span class="landing-step-num">2</span><h3>Send the first full-stack request</h3><p>Follow the tutorials from a real request; every chapter maps to runnable commands and test entries.</p></a><a class="landing-step" href="tutorials/example-removal"><span class="landing-step-num">3</span><h3>Compose or remove the example</h3><p>Remove the reference example block by block per the ownership manifest; Core keeps running, with static checks guarding the boundaries.</p></a><a class="landing-step" href="tutorials/single-machine-production"><span class="landing-step-num">4</span><h3>Deploy, back up, restore</h3><p>Single-machine compose production with degradation verification, plus backup archives and isolated-environment restore drills.</p></a></div></section><section class="landing-section"><h2 class="landing-heading">Real capabilities</h2><p class="landing-section-lede"> Everything below is delivered, each with tutorial chapters, automated tests and gates — not planned items. The item-by-item ledger lives in <a href="architecture/v1-coverage">v1 capability coverage and acceptance</a>. </p><div class="landing-grid"><a class="landing-card" href="tutorials/registration"><span class="landing-dot"></span><h3>Registration, sign-in and sessions</h3><p>Transactional registration and sign-in, session invalidation and multi-device management, verified against API tests and real browser journeys.</p></a><a class="landing-card" href="tutorials/members"><span class="landing-dot dot-green"></span><h3>Members and the last owner</h3><p>Role changes and deactivation revoke sessions immediately, and last-owner protection keeps the organization reachable.</p></a><a class="landing-card" href="tutorials/password-reset"><span class="landing-dot dot-amber"></span><h3>Password reset and reliable email</h3><p>Registration and reset mail lands in Mailpit in the development stack; production switches to a real SMTP server.</p></a><a class="landing-card" href="tutorials/rate-limits"><span class="landing-dot dot-red"></span><h3>Rate limits and degradation</h3><p>Redis-backed rate limits degrade conservatively: when the cache is down the service keeps answering, and the system page shows real status.</p></a><a class="landing-card" href="tutorials/electron-shell"><span class="landing-dot dot-cyan"></span><h3>Electron desktop shell</h3><p>The same web pages enter a secure desktop shell; IPC contract tests and the desktop smoke run in CI.</p></a><a class="landing-card" href="tutorials/single-machine-production"><span class="landing-dot dot-blue"></span><h3>Single-machine production</h3><p>A compose production stack with degradation verification; the public tutorial covers the whole path from certificates to fallback.</p></a><a class="landing-card" href="tutorials/backup-restore"><span class="landing-dot dot-green"></span><h3>Backup and restore drills</h3><p>Backup archives carry no secrets; a restore into an isolated environment verifies documents, attachments and jobs.</p></a></div></section><section class="landing-section"><h2 class="landing-heading">The reference example: a personal knowledge base</h2><p class="landing-section-lede"> A removable reference business that shows how business constraints, concurrency and resource authorization compose on top of Core; the boundaries and the removal steps live in <a href="tutorials/example-removal">Compose and remove reference examples</a>. </p><div class="landing-grid"><a class="landing-card" href="tutorials/personal-documents"><span class="landing-dot"></span><h3>Your first Markdown document</h3><p>Document CRUD with safe body rendering.</p></a><a class="landing-card" href="tutorials/search-preview"><span class="landing-dot dot-cyan"></span><h3>Title search and safe preview</h3><p>Title search, pagination and a preview that never executes scripts.</p></a><a class="landing-card" href="tutorials/edit-conflicts"><span class="landing-dot dot-amber"></span><h3>Explicit saves and version conflicts</h3><p>Concurrent saves trigger a 409 with an understandable conflict flow.</p></a><a class="landing-card" href="tutorials/library-grants"><span class="landing-dot dot-purple"></span><h3>Shared knowledge bases and grants</h3><p>Reader/Editor grants, revocations and permission inheritance.</p></a><a class="landing-card" href="../tutorials/attachments"><span class="landing-dot dot-green"></span><h3>RustFS attachments</h3><p>Attachment upload and download over real object storage, hashing and browser CORS.</p></a><a class="landing-card" href="../tutorials/document-exports"><span class="landing-dot dot-red"></span><h3>Exports and jobs</h3><p>ZIP exports run as PostgreSQL Jobs; failures are retried by an administrator.</p></a><a class="landing-card" href="../tutorials/api-keys"><span class="landing-dot dot-purple"></span><h3>API keys and resource permissions</h3><p>Issue a key that reads the knowledge documents it is permitted to read, with the scope verifiable.</p></a></div></section><section class="landing-section landing-closing"><h2 class="landing-heading">Start with the documentation</h2><p class="landing-lede"> The tutorials evolve in lockstep with the source: every chapter can be followed, verified, and replaced wholesale with your own business. </p><p class="landing-actions"><a class="landing-button landing-button-primary" href="docs/">Documentation</a><a class="landing-button" href="getting-started/quickstart">Quick start</a></p></section></div><hr><p>Source version：<code>d209def654c8</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/d209def654c8bab1a92fe98f8cd614cc87b674d4/docs/index.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>',3)])])}const u=e(i,[["render",r]]);export{g as __pageData,u as default};
